begin;
create temp table junk as select id from customers where email like '%@acme-internal.test';
do $$ begin if (select count(*) from junk) <> 12 then raise exception 'expected 12 test customers'; end if; end $$;
with d as (delete from invoices where customer_id in (select id from junk) returning 1) select count(*) as invoices_deleted from d;
with d as (delete from subscriptions where customer_id in (select id from junk) returning 1) select count(*) as subs_deleted from d;
with d as (delete from customers where id in (select id from junk) returning 1) select count(*) as customers_deleted from d;
do $$ begin if (select count(*) from customers) <> 201 then raise exception 'unexpected remaining count'; end if; end $$;
commit;
select * from dashboard_summary;
SQL

